def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search for O(n log n).
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # find position to insert x in tails
        idx = bisect.bisect_left(tails, x)
        # ensure strictly increasing: bisect_left works because we replace equal values
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

