{"task_id": "T25", "code": "def solve(matrix):
    # Bareiss algorithm for integer determinant
    n = len(matrix)
    if n == 0:
        return 1
    # make a copy
    A = [row[:] for row in matrix]
    det = 1
    for k in range(n-1):
        # find non-zero pivot; if zero, swap with lower row
        if A[k][k] == 0:
            swap_row = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            det = -det
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Update using Bareiss formula
                A[i][j] = (A[i][j]*A[k][k] - A[i][k]*A[k][j]) // (A[k-1][k-1] if k>0 else 1)
        # Zero out column k below diagonal
        for i in range(k+1, n):
            A[i][k] = 0
    det *= A[n-1][n-1]
    return det
