def solve(n):
    """Return the count of prime numbers strictly less than ``n``.
    Uses a classic Sieve of Eratosthenes with a Python list of booleans.
    This implementation is simple and handles all edge cases reliably.
    """
    if n <= 2:
        return 0
    # is_prime[i] indicates whether i is prime for 0 <= i < n
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    import math
    limit = int(math.isqrt(n - 1))
    for p in range(2, limit + 1):
        if is_prime[p]:
            step = p
            start = p * p
            for multiple in range(start, n, step):
                is_prime[multiple] = False
    return sum(is_prime)

