        except Exception:
            continue
        # Preserve original type (int if both ints)
        if isinstance(a, int) and isinstance(b, int):
            a_val, b_val = int(a_val), int(b_val)
        if a_val > b_val:
            a_val, b_val = b_val, a_val
        norm.append([a_val, b_val])
    if not norm:
        return []
    # Sort by start
    norm.sort(key=lambda x: x[0])
    merged = [norm[0][:]]
    for start, end in norm[1:]:
