def solve(s):
    """Return True if s is a valid IPv4 address.
    Rules:
    - Exactly four decimal numbers separated by '.'
    - Each number 0-255 inclusive
    - No leading zeros unless the number is exactly '0'
    - Only digits allowed in each part
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        if not part.isdigit():
            return False
        # leading zero check
