def solve(s):
    """Convert a Roman numeral to its integer value.
    Handles standard subtractive notation. Assumes the input is a valid Roman numeral.
    """
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        val = values[ch]
        if val < prev:
            total -= val
        else:
            total += val
