def solve(nums=None):
    """Return the length of the longest strictly increasing subsequence.
    If the input is None or empty, returns 0.
    Uses patience sorting (binary search) for O(n log n) time.
    """
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # Find the insertion point for x in tails to maintain increasing order.
        # bisect_left ensures that equal values replace existing ones, keeping sequence strictly increasing.
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

