def solve(grid):
    """Count islands in a possibly irregular grid.
    Cells are considered land if they are truthy and not zero/"0".
    Connectivity is four-directional (up, down, left, right).
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def is_land(val):
        # Accept 1, '1', True, any non-zero int, etc.
        if isinstance(val, str):
            return val != '0' and val != ''
        return bool(val)
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            # bounds check for irregular rows
            if i < 0 or i >= rows:
                continue
            row = grid[i]
            if j < 0 or j >= len(row):
                continue
            if not is_land(row[j]):
                continue
            visited.add((i, j))
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if is_land(val) and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

