def solve(matrix):
    """Return the determinant of a square integer matrix.
    Uses Gaussian elimination with exact rational arithmetic (Fraction).
    An empty matrix (size 0) has determinant 1 by definition.
    """
    from fractions import Fraction
    n = len(matrix)
    if n == 0:
        return 1
    # Make a copy as Fraction matrix
    A = [[Fraction(elem) for elem in row] for row in matrix]
    det = Fraction(1)
    for i in range(n):
        # Find pivot
        pivot = i
        while pivot < n and A[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0  # singular matrix
        if pivot != i:
            # swap rows
            A[i], A[pivot] = A[pivot], A[i]
            det *= -1
        pivot_val = A[i][i]
        det *= pivot_val
        # Normalize row i
        for j in range(i, n):
            A[i][j] /= pivot_val
        # Eliminate below
        for k in range(i+1, n):
            factor = A[k][i]
            if factor != 0:
                for j in range(i, n):
                    A[k][j] -= factor * A[i][j]
    # det is Fraction, should be integer
    return int(det)

