def solve(s):
    # Accept strings or any iterable of characters
    if not isinstance(s, str):
        # Convert to a string representation if it's not iterable of characters
        try:
            seq = list(s)
        except Exception:
            s = str(s)
            seq = s
    else:
        seq = s
    seen = {}
    left = 0
    best = 0
    for right, ch in enumerate(seq):
        prev = seen.get(ch)
        if prev is not None and prev >= left:
            left = prev + 1
        seen[ch] = right
        cur_len = right - left + 1
        if cur_len > best:
            best = cur_len
    return best
